"use client";

import { Switch as SwitchPrimitive } from "@base-ui/react/switch";

import { cn } from "@/lib/utils";
import { controlChecked, focusRing, wellInset } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Burnished Switch: a 2.75rem by 1.5rem track. Off, the track is a recessed
 * well and the knob is a raised graphite bevel. On, the track takes the
 * primary's cream bevel and the knob turns cream, sliding across on the
 * soft ease-out.
 */
function Switch({ className, ...props }: WithClassName<SwitchPrimitive.Root.Props>) {
  return (
    <SwitchPrimitive.Root
      data-slot="switch"
      className={cn(
        "peer inline-flex h-6 w-11 shrink-0 cursor-pointer items-center rounded-full p-0.5",
        wellInset,
        "transition-[box-shadow,background-image] duration-base ease-(--ease-out)",
        focusRing,
        "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
        controlChecked,
        className,
      )}
      {...props}
    >
      <SwitchPrimitive.Thumb
        data-slot="switch-thumb"
        className={cn(
          "pointer-events-none block size-5 rounded-full",
          "bg-(image:--fill-raised) shadow-(--bevel-raised)",
          "transition-[translate,background-image] duration-base ease-(--ease-out)",
          "data-[checked]:translate-x-5 data-[unchecked]:translate-x-0 rtl:data-[checked]:-translate-x-5",
          "data-[checked]:bg-(image:--fill-primary) data-[checked]:shadow-(--bevel-primary)",
        )}
      />
    </SwitchPrimitive.Root>
  );
}
Switch.displayName = "Switch";

export { Switch };
